// Neatlogs: read side of run quality for Loop 4 (public API), plus status for the UI.
// Ingestion is done by Neatlogs' own Claude Code plugin / Codex hooks (see execute_yourself.md).
const { env } = require("./env.cjs");

const base = () =>
  (env("NEATLOGS_REGION") === "eu"
    ? "https://eu.app.neatlogs.com"
    : "https://app.neatlogs.com") + "/api/v1/public";
const configured = () =>
  Boolean(env("NEATLOGS_API_KEY") && env("NEATLOGS_PROJECT_ID"));

async function api(p, init = {}) {
  const timeoutMs = init.timeoutMs || 15000;
  const request = { ...init };
  delete request.timeoutMs;
  const res = await fetch(`${base()}${p}`, {
    ...request,
    signal: request.signal || AbortSignal.timeout(timeoutMs),
    headers: {
      Authorization: `Bearer ${env("NEATLOGS_API_KEY")}`,
      "x-project-id": env("NEATLOGS_PROJECT_ID"),
      "Content-Type": "application/json",
      ...(request.headers || {}),
    },
  });
  if (!res.ok) throw new Error(`Neatlogs ${p}: ${res.status}`);
  const j = await res.json();
  return j.data ?? j;
}

async function recentTraces(limit = 20) {
  if (!configured()) return [];
  const d = await api(`/traces?limit=${limit}`);
  return Array.isArray(d) ? d : d.items || d.traces || [];
}

async function searchTraces(query) {
  if (!configured()) return [];
  return api("/search/traces", {
    method: "POST",
    body: JSON.stringify({ query }),
  });
}

function traceItems(value) {
  return Array.isArray(value)
    ? value
    : value?.traces || value?.spans || value?.items || value?.results || [];
}

async function evidence(run, deps = {}) {
  if (!configured())
    return {
      source: "neatlogs",
      configured: false,
      matched: false,
      traces: [],
      error: "Set NEATLOGS_API_KEY and NEATLOGS_PROJECT_ID to link traces.",
    };
  if (!run.sessionId)
    return {
      source: "neatlogs",
      configured: true,
      matched: false,
      traces: [],
      matchReason:
        "The agent did not report a session identifier, so Benana cannot attribute a trace.",
    };
  const request = deps.api || api;
  try {
    const listed = traceItems(
      await request(
        `/traces?limit=20&sessionId=${encodeURIComponent(run.sessionId)}`,
      ),
    );
    const exact = listed.filter(
      (trace) =>
        String(trace.sessionId || trace.session_id || "") ===
        String(run.sessionId),
    );
    const traces = [];
    for (const trace of exact) {
      const id = trace.traceId || trace.trace_id || trace.id;
      let spans = [];
      let spansError;
      if (id) {
        try {
          spans = traceItems(
            await request(`/traces/${encodeURIComponent(id)}/spans?limit=50`),
          );
        } catch (error) {
          spansError = error.message;
        }
      }
      traces.push({ ...trace, spans, ...(spansError ? { spansError } : {}), raw: { trace, spans } });
    }
    return {
      source: "neatlogs",
      configured: true,
      matched: traces.length > 0,
      traces,
      matchReason: traces.length
        ? `Matched exact agent session ${run.sessionId}.`
        : `No trace matched exact agent session ${run.sessionId}.`,
    };
  } catch (error) {
    return {
      source: "neatlogs",
      configured: true,
      matched: false,
      traces: [],
      error: error.message,
    };
  }
}

async function status() {
  if (!configured()) return { configured: false };
  try {
    const t = await recentTraces(5);
    return { configured: true, ok: true, recent: t.length };
  } catch (e) {
    return { configured: true, ok: false, error: e.message };
  }
}

module.exports = {
  configured,
  evidence,
  recentTraces,
  searchTraces,
  status,
  traceItems,
};
import React from "react";
import { call, on } from "../../api.js";
import TestPanel, { useNow, useStickyScroll } from "./TestPanel.jsx";
import {
  CheckIcon,
  Icon,
  PHASES,
  ROLE,
  Status,
  fmtDuration,
  fmtMoney,
  latestVerdict,
  modSpend,
  phaseIndex,
  shortModel,
  turnAttempts,
  turnsOf,
} from "./shared.jsx";

const EXAMPLES = [
  "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.",
  "Arrows that explode on impact without breaking blocks, with a 5 second cooldown per player.",
  "Right-clicking with a blaze rod shoots a fireball where you look.",
];

const STEP_DETAIL = {
  spec: "Turn the idea into a plugin spec and an in-game test plan",
  repo: "Create the mod repository with Entire and Neatlogs hooks",
  build: "Write the Paper plugin",
  compile: "Package it with Maven",
  deploy: "Load it on the Paper server",
  playtest: "An AI player runs every check in-game",
  fix: "Patch failures from the evidence, up to 3 attempts",
  done: "Report the result",
};

// A follow-up message changes the existing plugin, so the repository step is already done.
const REVISION_DETAIL = {
  spec: "Update the plugin spec and test plan for your change",
  repo: "Already set up",
  build: "Change the existing plugin",
};

export default function BuildPage({ mod, running, lessons, onCreated, onWatch, onNew, onOpenCode }) {
  const [prompt, setPrompt] = React.useState("");
  return (
    <div className="build-chat">
      <section className="chat">
        <ChatHead mod={mod} onNew={onNew} onOpenCode={onOpenCode} />
        {mod ? <Thread mod={mod} onOpenCode={onOpenCode} /> : <Welcome lessons={lessons} onPick={setPrompt} />}
        <Composer
          mod={mod}
          running={running}
          prompt={prompt}
          setPrompt={setPrompt}
          onCreated={onCreated}
          onWatch={onWatch}
        />
      </section>
      <TestPanel mod={mod} building={Boolean(running)} />
    </div>
  );
}

function ChatHead({ mod, onNew, onOpenCode }) {
  return (
    <header className="chat-head">
      <div className="chat-title">
        {mod ? (
          <>
            <strong>{mod.name}</strong>
            <Status status={mod.running ? "running" : mod.status} />
            {mod.seed && <span className="tag">Seeded bug</span>}
          </>
        ) : (
          <strong>New mod</strong>
        )}
      </div>
      {mod && (
        <div className="page-actions">
          {mod.running && (
            <button className="btn danger sm" onClick={() => call("studio:stop", { id: mod.id })}>
              <Icon name="stop" size={13} />
              Stop
            </button>
          )}
          {mod.repoDir && (
            <button className="btn sm" onClick={() => onOpenCode(mod.id)}>
              <Icon name="code" size={13} />
              Code
            </button>
          )}
          {!mod.running && (
            <button className="btn sm" onClick={onNew}>
              <Icon name="plus" size={13} />
              New
            </button>
          )}
        </div>
      )}
    </header>
  );
}

function Welcome({ lessons, onPick }) {
  return (
    <div className="thread welcome-wrap">
      <div className="intro">
        <span className="welcome-mark">B</span>
        <h1>What should your mod do?</h1>
        <p>Describe a gameplay idea. Benana writes the Paper plugin, an AI player tests it on a live server, and a fixer patches anything that breaks.</p>
        <div className="ideas">
          {EXAMPLES.map((ex) => (
            <button key={ex} onClick={() => onPick(ex)}>
              <Icon name="spark" size={14} />
              <span>{ex}</span>
            </button>
          ))}
        </div>
        {lessons.length > 0 && (
          <div className="welcome-lessons">
            <span className="side-label">
              The fixer has learned {lessons.length} lesson{lessons.length === 1 ? "" : "s"}
            </span>
            <p>{lessons.at(-1).lesson}</p>
          </div>
        )}
      </div>
    </div>
  );
}

function Composer({ mod, running, prompt, setPrompt, onCreated, onWatch }) {
  const [seedOn, setSeed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState("");
  const ref = React.useRef(null);
  // One chat is one mod: with a mod open, a message changes that mod. Only a new chat starts a new mod.
  const seed = seedOn && !mod;
  const canStart = !busy && !running && (seed || prompt.trim().length >= 8);
  const placeholder = running
    ? mod?.running
      ? "Building… ask for changes when it finishes"
      : "One mod builds at a time. Describe the next one…"
    : mod
      ? mod.repoDir
        ? `Ask for a change to ${mod.name}…`
        : "Add detail and try building again…"
      : "A golden sword that launches mobs into the sky…";

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 180)}px`;
  }, [prompt]);

  const start = async () => {
    if (!canStart) return;
    setBusy(true);
    setError("");
    try {
      if (mod) {
        await call("studio:revise", { id: mod.id, prompt });
        setPrompt("");
      } else {
        const created = await call("studio:create", { prompt, seed });
        setPrompt("");
        onCreated(created.id);
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="composer-wrap">
      {mod?.running && <Dock mod={mod} />}
      {running && running.id !== mod?.id && (
        <button className="dock dock-link" onClick={() => onWatch(running.id)}>
          <span className="spinner" />
          <span>
            <strong>{running.name}</strong> is building
          </span>
          <span className="dock-cta">
            Watch <Icon name="arrow" size={13} />
          </span>
        </button>
      )}
      {error && <div className="alert">{error}</div>}
      <div className={`chat-input ${seed ? "seeded" : ""} ${running ? "locked" : ""}`}>
        <textarea
          ref={ref}
          rows={1}
          value={prompt}
          disabled={seed}
          aria-label={mod ? "Ask for a change" : "Describe a mod"}
          placeholder={placeholder}
  const result = await handle.done;
  Object.assign(session, { endedAt: now(), ok: result.ok, error: result.error, usage: result.usage, sessionId: result.sessionId || session.sessionId });
  save(mod);
  if (active?.stopped) throw new Error('Stopped by user.');
  return result;
}

async function specPhase(mod, turn) {
  if (mod.seed && !turn.revision) {
    const seeded = JSON.parse(fs.readFileSync(path.join(SEEDED, 'spec.json'), 'utf8'));
    feed(mod, { role: 'benana', kind: 'note', text: 'Seeded bug fallback: using the labeled LaunchSword fixture spec instead of the spec agent.' });
    return seeded;
  }
  const work = path.join(studioDir, mod.id, 'spec');
  fs.mkdirSync(work, { recursive: true });
  const prompt = turn.revision ? prompts.specRevision({ mod, request: turn.prompt }) : prompts.spec(prompts.requestOf(mod));
  const res = await agent(mod, null, 'spec', { cwd: work, prompt, model: MODELS.build, tools: [] });
  if (!res.ok) throw new Error(`Spec agent failed: ${res.error}`);
  const spec = parseJson(res.final);
  // A revised plugin keeps the name its repository, jar and main class already use.
  if (turn.revision) spec.modName = mod.name;
  else if (!/^[A-Za-z]{2,24}$/.test(spec.modName || '')) spec.modName = 'StudioMod';
  if (!spec.testPlan?.checks?.length) throw new Error('Spec agent returned no test checks.');
  spec.testPlan.modName = spec.modName;
  return spec;
}

async function trace(sessionId) {
  if (!sessionId || !neatlogs.configured()) return '';
  const ev = await neatlogs.evidence({ sessionId });
  if (!ev.matched) return '';
  return ev.traces.map((t) => {
    const spans = (t.spans || []).slice(0, 25).map((s) => `  - ${s.name || s.span_name || 'span'}${s.status === 'error' || s.status_code === 'ERROR' ? ' (error)' : ''}`).join('\n');
    return `trace ${t.traceId || t.trace_id || t.id}\n${spans}`;
  }).join('\n').slice(0, 4000);
}

async function codePhase(mod, attempt, previous) {
  if (attempt.role === 'seeded') {
    fs.copyFileSync(path.join(SEEDED, 'LaunchSword.java'), path.join(mod.repoDir, 'src', 'main', 'java', 'dev', 'benana', 'mod', 'LaunchSword.java'));
    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: 'Seeded bug fallback: attempt 1 uses the labeled fixture source (velocity set inside the damage event).' });
    return;
  }
  const lessonList = lessons().map((l) => l.lesson);
  if (attempt.role === 'builder') {
    const prompt = attempt.revision
      ? prompts.reviser({ mod, attempt, request: mod.turns[attempt.turn].prompt, lessons: lessonList })
      : prompts.builder({ mod, lessons: lessonList });
    const res = await agent(mod, attempt, 'builder', { cwd: mod.repoDir, prompt, model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
    if (!res.ok) throw new Error(`Builder failed: ${res.error}`);
    attempt.summary = res.final.slice(0, 2000);
    return;
  }
  const cps = await repo.checkpoints(mod.repoDir);
  const context = {
    history: await repo.history(mod.repoDir),
    checkpoints: cps.ok ? cps.items.slice(0, 8).map((c) => `${c.checkpoint_id} "${c.message}" session ${c.session_id} (${c.agent})`).join('\n') : '',
    trace: await trace(previous.sessions.find((s) => s.role === 'playtester')?.sessionId).catch(() => ''),
  };
  attempt.context = { entireCheckpoints: cps.ok ? cps.items.length : 0, neatlogsTrace: Boolean(context.trace) };
  const res = await agent(mod, attempt, 'fixer', { cwd: mod.repoDir, prompt: prompts.fixer({ mod, attempt, previous, context }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
  if (!res.ok) throw new Error(`Fixer failed: ${res.error}`);
  attempt.summary = res.final.slice(0, 2000);
  const lesson = res.final.match(/^LESSON:\s*(.+)$/m);
  if (lesson) attempt.lesson = lesson[1].trim();
}

async function playtestPhase(mod, attempt) {
  const dir = path.join(mod.repoDir, 'playtest', `attempt-${attempt.n}`);
  fs.mkdirSync(dir, { recursive: true });
  const verdictFile = path.join(dir, 'verdict.json');
  const testPlanFile = path.join(mod.repoDir, 'playtest', 'test-plan.json');
  fs.rmSync(verdictFile, { force: true });

  if (game.status().mock) {
    const v = game.mockVerdict(mod.testPlan, attempt.n);
    fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
    feed(mod, { attempt: attempt.n, role: 'playtester', kind: 'note', text: '[mock runtime] canned verdict' });
    return game.readVerdict(verdictFile, mod.testPlan);
  }

  for (let run = 1; run <= 2; run++) {
    const mcpFile = path.join(studioDir, mod.id, `mcp-attempt-${attempt.n}.json`);
    fs.mkdirSync(path.dirname(mcpFile), { recursive: true });
    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId: `${mod.id}_${attempt.n}`, verdictFile, testPlanFile })));
    const poll = setInterval(() => {
      if (!fs.existsSync(verdictFile)) return;
      const live = game.readVerdict(verdictFile, mod.testPlan);
      attempt.verdict = { ...live, live: true };
      save(mod);
    }, 1000);
    try {
      await agent(mod, attempt, 'playtester', { cwd: mod.repoDir, prompt: game.playtestPrompt(mod.testPlan), model: MODELS.playtest, tools: [], allowedTools: game.playtesterTools, mcpConfigFile: mcpFile });
    } finally {
      clearInterval(poll);
    }
    const verdict = game.readVerdict(verdictFile, mod.testPlan);
    if (verdict.finished) return verdict;
    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: run === 1 ? 'The playtester stopped before finishing; running it again.' : 'The playtester did not finish the test plan.' });
  }
  return game.readVerdict(verdictFile, mod.testPlan);
}

