// Runs one headless Claude Code session and streams its activity.
// Sessions run inside the mod repo so the repo's Entire and Neatlogs hooks capture them.
const { spawnExecutable, terminateProcessTree } = require('../processes.cjs');
const { normalizeUsage } = require('../providers.cjs');

const MODELS = { build: 'opus', playtest: 'sonnet' };

function summarize(input) {
  const text = JSON.stringify(input ?? {});
  return text.length > 240 ? `${text.slice(0, 240)}…` : text;
}

function resultText(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) return content.map((c) => c.text || '').join('\n');
  return JSON.stringify(content ?? '');
}

/**
 * @returns {{ done: Promise<{ok, sessionId, final, usage, error}>, stop: () => void }}
 */
function runClaude({ cwd, prompt, model, tools, allowedTools = [], mcpConfigFile, appendSystemPrompt, timeoutMs = 20 * 60 * 1000, onEvent = () => {} }) {
  const args = ['-p', '--output-format', 'stream-json', '--verbose', '--model', model, '--permission-mode', 'acceptEdits', '--setting-sources', 'project,local'];
  if (tools) args.push('--tools', tools.join(','));
  if (allowedTools.length) args.push('--allowedTools', allowedTools.join(','));
  if (mcpConfigFile) args.push('--mcp-config', mcpConfigFile, '--strict-mcp-config');
  if (appendSystemPrompt) args.push('--append-system-prompt', appendSystemPrompt);

  const env = { ...process.env };
  delete env.ELECTRON_RUN_AS_NODE;
  const child = spawnExecutable('claude', args, { cwd, stdio: ['pipe', 'pipe', 'pipe'], env });
  const run = { sessionId: null, final: '', usage: null, error: null, stopped: false };
  const names = new Map();

  const done = new Promise((resolve) => {
    let buf = '';
    let stderr = '';
    const timer = setTimeout(() => { run.error = `Timed out after ${Math.round(timeoutMs / 60000)} minutes.`; terminateProcessTree(child); }, timeoutMs);
    const handle = (line) => {
      let ev;
      try { ev = JSON.parse(line); } catch { return; }
      if (ev.type === 'system' && ev.session_id) {
        if (!run.sessionId) onEvent({ kind: 'session', sessionId: ev.session_id, model });
        run.sessionId = ev.session_id;
      } else if (ev.type === 'assistant') {
        for (const item of ev.message?.content || []) {
          if (item.type === 'text' && item.text.trim()) onEvent({ kind: 'text', text: item.text.trim() });
          if (item.type === 'tool_use') {
            names.set(item.id, item.name);
            onEvent({ kind: 'tool', name: item.name.replace(/^mcp__\w+?__/, ''), input: item.input, summary: summarize(item.input) });
          }
        }
      } else if (ev.type === 'user') {
        for (const item of ev.message?.content || []) {
          if (item.type !== 'tool_result') continue;
          const name = (names.get(item.tool_use_id) || 'tool').replace(/^mcp__\w+?__/, '');
          onEvent({ kind: 'result', name, isError: Boolean(item.is_error), text: resultText(item.content).slice(0, 1500) });
        }
      } else if (ev.type === 'result') {
        run.final = ev.result || '';
        run.usage = normalizeUsage(ev.usage, ev);
        if (ev.is_error) run.error = String(ev.result || 'Claude reported an error.');
      }
    };
    child.stdout.on('data', (d) => {
      buf += d;
      const lines = buf.split(/\r?\n/);
      buf = lines.pop();
      lines.filter(Boolean).forEach(handle);
    });
    child.stderr.on('data', (d) => { stderr = (stderr + d).slice(-4000); });
    child.on('error', (e) => { run.error = `Could not start Claude Code: ${e.message}`; });
    child.on('close', (code) => {
      clearTimeout(timer);
      if (buf.trim()) handle(buf);
      if (run.stopped) run.error = 'Stopped.';
      else if (code !== 0 && !run.error) run.error = stderr.trim() || `Claude exited with code ${code}.`;
      resolve({ ok: !run.error, sessionId: run.sessionId, final: run.final, usage: run.usage, error: run.error });
    });
  });

  child.stdin.end(prompt);
  return { done, stop: () => { run.stopped = true; terminateProcessTree(child); } };
}

module.exports = { runClaude, MODELS };
function NeatlogsLane({ mod }) {
  const [status, setStatus] = React.useState(null);
  const [evidence, setEvidence] = React.useState({});
  const pending = React.useRef(new Set());
  const sessions = React.useMemo(
    () => (mod ? allSessions([mod]).filter((s) => s.sessionId).reverse() : []),
    [mod],
  );
  const running = sessions.some((s) => !s.endedAt);
  const now = useNow(running);

  React.useEffect(() => {
    call("studio:partners")
      .then((p) => setStatus(p.neatlogs))
      .catch(() => setStatus({ configured: true, ok: false }));
  }, []);

  const timers = React.useRef({});
  const clearTimers = () => {
    Object.values(timers.current).forEach(clearTimeout);
    timers.current = {};
  };
  React.useEffect(() => clearTimers, []);

  React.useEffect(() => {
    clearTimers();
    setEvidence({});
    pending.current = new Set();
  }, [mod?.id]);

  React.useEffect(() => {
    if (status?.configured === false) return;
    for (const s of sessions) {
      const id = s.sessionId;
      if (!s.endedAt || pending.current.has(id)) continue;
      const prev = evidence[id];
      if (prev && (prev.matched || prev.configured === false || prev.tries >= 3)) continue;
      pending.current.add(id);
      const lookup = () =>
        call("studio:evidence", { sessionId: id })
          .catch((e) => ({ matched: false, traces: [], error: e.message }))
          .then((r) => {
            pending.current.delete(id);
            delete timers.current[id];
            setEvidence((m) => ({ ...m, [id]: { ...r, tries: (m[id]?.tries || 0) + 1 } }));
          });
      if (prev) timers.current[id] = setTimeout(lookup, RETRY_MS);
      else lookup();
    }
  }, [sessions, evidence, status?.configured]);

  const matched = Object.values(evidence).filter((e) => e.matched).length;
  const { ref, onScroll } = useStickyScroll(sessions.length + matched);

  return (
    <section className="lane">
      <header className="lane-head">
        <span className="lane-mark neatlogs" />
        <strong>Neatlogs</strong>
        {running && <span className="lane-live on">Tracing</span>}
        <span className="lane-meta">
          {status?.configured === false ? "Not configured" : `${matched}/${sessions.length} traced`}
        </span>
      </header>
      <div className="lane-body" ref={ref} onScroll={onScroll}>
        {!sessions.length && (
          <p className="lane-empty">
            {status?.configured === false
              ? "Add NEATLOGS_API_KEY and NEATLOGS_PROJECT_ID to .env to trace agent sessions."
              : "Each agent session is traced here as it runs."}
          </p>
        )}
        {sessions.map((s) => {
          const ev = evidence[s.sessionId];
          const trace = ev?.traces?.[0];
          const spans = trace?.spans || [];
          const live = !s.endedAt;
          return (
            <article key={s.key} className={`ntrace ${live ? "live" : ev?.matched ? "matched" : ""}`}>
              <div className="trace-row">
                <span className={`role-dot ${s.role}`} />
                <strong>{ROLE[s.role] || s.role}</strong>
                <span className="lane-meta">{s.attemptN ? `attempt ${s.attemptN}` : "spec"}</span>
                <span className="trace-state">
                  {live
                    ? `Tracing · ${fmtDuration(now - s.startedAt)}`
                    : status?.configured === false
                      ? "Not configured"
                      : !ev
                        ? "Looking up trace…"
                        : ev.matched
                          ? `${spans.length} spans`
                          : ev.tries >= 3
                            ? "No trace found"
                            : "Waiting for trace…"}
                </span>
              </div>
              <div className="trace-sub">
                <code>{s.sessionId.slice(0, 18)}</code>
                <span>{shortModel(s.model)}</span>
                {trace?.durationMs != null && <span>{fmtDuration(trace.durationMs)}</span>}
    </section>
  );
}

export function TraceButton({ sessionId }) {
  const [trace, setTrace] = React.useState(null);
  if (!sessionId) return null;
  const label = trace
    ? trace.matched
      ? `${trace.traces.length} trace${trace.traces.length === 1 ? "" : "s"}`
      : trace.configured === false
        ? "Not configured"
        : "No trace yet"
