              ? `No playtest ran in attempt ${from?.n ?? n - 1} because ${reason}, so there is no trace to read.`
              : NO_TRACE[nl?.state] || (nl?.error ? `Could not read the trace: ${nl.error}` : "No playtest trace was read.")}
          </span>
