.studio .handoff-seq span em {
  margin-left: 3px;
  color: var(--text-3);
  font-style: normal;
}
.studio .handoff-seq span.err {
  border-color: rgba(229, 72, 77, 0.35);
  background: var(--bad-soft);
  color: var(--bad-text);
}
.studio .handoff-seq span.more {
  border-style: dashed;
  color: var(--text-3);
}
